import 'dart:convert';

import 'package:flutter/services.dart';

/// Per-ayah durations for EveryAyah reciters, generated by
/// `tool/fetch_audio_durations.py` and bundled as an asset.
class AudioDurationIndex {
  AudioDurationIndex._(this._reciters);

  final Map<String, Map<int, List<int>>> _reciters;

  static AudioDurationIndex? _instance;

  static AudioDurationIndex get instance =>
      _instance ?? AudioDurationIndex._(const {});

  static Future<AudioDurationIndex> load({AssetBundle? bundle}) async {
    final cached = _instance;
    if (cached != null) return cached;
    try {
      final raw = await (bundle ?? rootBundle).loadString(
        'assets/data/audio_durations.json',
      );
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      _instance = AudioDurationIndex.fromJson(decoded);
      return _instance!;
    } catch (_) {
      _instance = AudioDurationIndex._(const {});
      return _instance!;
    }
  }

  factory AudioDurationIndex.fromJson(Map<String, dynamic> decoded) {
    final reciters = <String, Map<int, List<int>>>{};
    for (final reciter in decoded.entries) {
      final surahs = reciter.value;
      if (surahs is! Map) continue;
      final parsed = <int, List<int>>{};
      for (final surah in surahs.entries) {
        final number = int.tryParse('${surah.key}');
        final list = surah.value;
        if (number == null || list is! List) continue;
        parsed[number] = [
          for (final value in list)
            if (value is num) value.toInt() else 0,
        ];
      }
      reciters[reciter.key] = parsed;
    }
    return AudioDurationIndex._(reciters);
  }

  List<int>? durationsFor(String reciterId, int surah) =>
      _reciters[reciterId]?[surah];

  bool isComplete(String reciterId, int surah, int ayahCount) {
    final list = durationsFor(reciterId, surah);
    return list != null &&
        list.length >= ayahCount &&
        list.take(ayahCount).every((duration) => duration > 0);
  }

  int? totalFor(String reciterId, int surah, int ayahCount) {
    if (!isComplete(reciterId, surah, ayahCount)) return null;
    return durationsFor(
      reciterId,
      surah,
    )!.take(ayahCount).fold<int>(0, (sum, value) => sum + value);
  }

  int? durationFor(String reciterId, int surah, int ayah) {
    final list = durationsFor(reciterId, surah);
    if (list == null || ayah < 1 || ayah > list.length) return null;
    return list[ayah - 1];
  }

  /// Milliseconds before [ayah] (1-based) if the whole prefix is known.
  int? beforeAyah(String reciterId, int surah, int ayah) {
    final list = durationsFor(reciterId, surah);
    if (list == null || ayah < 1 || ayah > list.length) return null;
    var sum = 0;
    for (var i = 0; i < ayah - 1; i++) {
      if (list[i] <= 0) return null;
      sum += list[i];
    }
    return sum;
  }

  /// 1-based ayah at an aggregate position, plus the offset inside it.
  ({int ayah, Duration offset})? locate(
    String reciterId,
    int surah,
    Duration position,
  ) {
    final list = durationsFor(reciterId, surah);
    if (list == null) return null;
    var remaining = position.inMilliseconds;
    for (var i = 0; i < list.length; i++) {
      final duration = list[i];
      if (duration <= 0) return null;
      if (remaining < duration) {
        return (ayah: i + 1, offset: Duration(milliseconds: remaining));
      }
      remaining -= duration;
    }
    return null;
  }
}
